import {loadCatalog, hydrateModel} from './data.js';
import {filterCards, makeRun, structureFor} from './logic.js';
const app=document.querySelector('#app');
const state={models:[],model:null,mode:'all',order:'sequential',tags:[],tagEffect:'include',advancedOpen:false,match:'all',run:null,index:0,revealed:false,hintShown:false,complete:false,query:'',tagQuery:''};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={start:'M8 5l11 7-11 7z',reveal:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',hint:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 18h.01','random-model':'M3 7h3l12 10h3 M17 13l4 4-4 4 M3 17h3l4-4 M14 9l4-2h3 M17 3l4 4-4 4',previous:'M19 12H5 M11 6l-6 6 6 6',next:'M5 12h14 M13 6l6 6-6 6'};
const icon=action=>icons[action]?`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[action]}"/></svg>`:'';
const button=(label,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${icon(action)}${label.replace(/[←→]/g,'').trim()}</button>`;
const segments=(values,current,action)=>`<div class="segments">${values.map(([value,label])=>button(label,action,'',`data-value="${value}" aria-pressed="${current===value}"`)).join('')}</div>`;
const selected=()=>state.model?filterCards(state.model.cards,state.mode,state.tags,state.match,state.tagEffect):[];
function library(){return `<aside class="library" aria-label="Models"><h2>Your models <span style="color:var(--muted);font-weight:400">/ ${state.models.length}</span></h2><input id="model-search" type="search" aria-label="Find a model" placeholder="Find a model…" value="${escape(state.query)}">${button('Random model','random-model','secondary random-model')}<div class="model-list">${modelList()}</div><p class="model-empty empty" hidden>No matching models.</p></aside>`;}
function modelList(){const models=state.models;return models.length?models.map(m=>`<button class="model" data-action="model" data-value="${m.id}" ${m.name.toLowerCase().includes(state.query.toLowerCase())?'':'hidden'} aria-pressed="${m.id===state.model?.id}"><img class="model-thumbnail" src="./${escape(m.image)}" alt="" loading="lazy" decoding="async" width="66" height="76"><span class="model-copy"><strong>${escape(m.name)}</strong><small>${m.count} cards · ${m.identificationCount} identification</small></span></button>`).join(''):'<p class="empty">No matching models.</p>';}
function tagChips(){const meta=state.models.find(m=>m.id===state.model?.id);if(!meta)return '';const query=state.tagQuery.trim().replace(/^#+/,'').toLowerCase();const tags=meta.tags.filter(t=>!/^([A-Z]{1,3}\d+(?:[_/]\d+)*)$/i.test(t)&&t.toLowerCase().includes(query));return tags.length?tags.map(t=>{const n=filterCards(state.model.cards,state.mode,[t],'all').length;return button(escape(t)+'<span>'+n+'</span>','tag','chip',`data-value="${escape(t)}" aria-pressed="${state.tags.includes(t)}"`)}).join(''):'<p class="empty" role="status">No matching tags. Try another search.</p>';}
function setup(){const m=state.model;if(!m)return '<p class="loading" role="status">Loading model…</p>';const meta=state.models.find(x=>x.id===m.id);return `<section class="workspace"><div class="model-overview"><div class="model-heading"><div class="eyebrow">Choose your revision</div><h1 class="model-title">${escape(m.name)}</h1><div class="stats"><span><b>${m.cards.length}</b> cards</span><span><b>${meta.identificationCount}</b> identification</span></div></div><figure class="model-photo"><img src="./${escape(meta.image)}" alt="${escape(m.name)} anatomy model" decoding="async" width="300" height="260"></figure></div><div class="panel options"><div><span class="option-label">Card set</span>${segments([['all','All cards'],['identification','Identification only']],state.mode,'mode')}</div><div><span class="option-label">Order</span>${segments([['sequential','In order'],['random','Random']],state.order,'order')}</div></div><details class="advanced-options panel" ${state.advancedOpen?'open':''}><summary>Advanced options${state.tags.length?`<span>${state.tags.length} tags ${state.tagEffect==='exclude'?'excluded':'selected'}</span>`:''}</summary><section><div class="filter-head"><h2>Tags</h2>${button('Clear filters','clear','text-button',state.tags.length?'':'disabled')}</div><p class="filter-help">${state.tags.length?`${state.tags.length} selected`:'All tags included'} · ${state.tagEffect==='exclude'?'Cards with selected tags are excluded.':'Cards must match selected tags.'}</p><div class="tag-mode-row">${segments([['include','Include'],['exclude','Exclude']],state.tagEffect,'tag-effect')}</div><div class="tag-mode-row" ${state.tagEffect==='exclude'?'hidden':''}>${segments([['all','Match all selected'],['any','Match any selected']],state.match,'match')}</div><label class="tag-search-label" for="tag-search">Find a tag</label><input id="tag-search" class="tag-search" type="search" placeholder="Search tags…" value="${escape(state.tagQuery)}" aria-controls="tag-results"><div class="chips" id="tag-results">${tagChips()}</div></section></details><div class="start-row"><div><strong>${selected().length} cards in this run</strong><p>${selected().length?'Every selected card, once. No scores or saved progress.':'No cards match. Try fewer tags or Match any selected.'}</p></div>${button('Start revision →','start','primary',selected().length?'':'disabled')}</div></section>`;}
function session(){if(state.complete)return `<section class="session"><div class="panel complete"><div class="complete-mark" aria-hidden="true">✓</div><div class="eyebrow">Run complete</div><h1>Every card covered.</h1><p>You reached the end of ${state.run.length} cards in<br>${escape(state.model.name)}.</p><div style="display:flex;flex-wrap:wrap;gap:12px;justify-content:center">${button('Start a fresh run','start','primary')}${button('Choose cards','exit')}</div></div></section>`;
const c=state.run[state.index];const identification=c.tags.includes('Identification');const structure=identification?'':structureFor(c,state.model.cards);return `<section class="session"><div class="session-top">${button('← Models & filters','exit','text-button')}<h1>${escape(state.model.name)}</h1><span class="session-count">${state.index+1} / ${state.run.length}</span></div><progress value="${state.index}" max="${state.run.length}" aria-label="Cards passed"></progress><article class="flashcard" tabindex="-1"><div class="card-meta"><span>${escape(c.section||'Model structures')}</span><span>${escape(c.question)}</span></div><div class="label-number">${escape(c.label||c.path.at(-1)||'—')}</div>${structure?((state.hintShown||state.revealed)?`<div class="structure" role="status">${escape(structure)}</div>`:button('Show structure name','hint','text-button structure-hint')):''}<h2 class="question">${identification?'Identify this structure':escape(c.question)}</h2>${state.revealed?`<div class="answer" role="status">${escape(c.answer)}</div><a class="structure-link" href="./library.html?structure=${encodeURIComponent(c.structureId)}">Explore this structure in the library</a>`:button('Reveal answer','reveal','primary reveal')}</article><div class="session-controls">${button('← Previous','previous','secondary',state.index?'':'disabled')}${button(state.index===state.run.length-1?'Finish run ✓':'Next card →','next','primary',state.revealed?'':'disabled')}</div><p class="shortcuts">Space to reveal · ← previous · → next after revealing</p></section>`;}
function updateLibrary(){const empty=app.querySelector('.model-empty');if(empty)empty.hidden=state.models.some(m=>m.name.toLowerCase().includes(state.query.toLowerCase()));
 const search=app.querySelector('#model-search');if(search)search.value=state.query;
 app.querySelectorAll('.model').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(state.query.toLowerCase());b.setAttribute('aria-pressed',String(b.dataset.value===state.model?.id));});
}
function render(){
 if(state.run){app.innerHTML=session();return;}
 const workspace=app.querySelector('.workspace');
 if(!workspace||!state.model){app.innerHTML=`<div class="layout">${library()}${setup()}</div>`;return;}
 updateLibrary();
 const template=document.createElement('template');template.innerHTML=setup();const next=template.content.firstElementChild;
 const currentPhoto=workspace.querySelector('.model-photo img'),newPhoto=next.querySelector('.model-photo img');
 if(currentPhoto.getAttribute('src')!==newPhoto.getAttribute('src')){currentPhoto.src=newPhoto.getAttribute('src');currentPhoto.alt=newPhoto.alt;}
 workspace.querySelector('.model-heading').innerHTML=next.querySelector('.model-heading').innerHTML;
 const focused=document.activeElement;const actionName=focused?.dataset?.action;const value=focused?.dataset?.value;
 const chipsScroll=workspace.querySelector('.chips')?.scrollTop||0;
 [...workspace.children].slice(1).forEach(node=>node.remove());
 [...next.children].slice(1).forEach(node=>workspace.append(node));
 workspace.querySelector('.chips').scrollTop=chipsScroll;
 if(actionName){const target=[...workspace.querySelectorAll('button')].find(b=>b.dataset.action===actionName&&b.dataset.value===value);target?.focus({preventScroll:true});}
}
let loadVersion=0;
async function choose(id){const version=++loadVersion;state.run=null;app.setAttribute('aria-busy','true');try{const meta=state.models.find(m=>m.id===id);if(!meta)throw Error('Unknown model');const response=await fetch('./data/'+meta.file);if(!response.ok)throw Error('Could not load model');const model=hydrateModel(await response.json(),await loadCatalog());if(version!==loadVersion)return;state.model=model;state.tags=[];state.tagQuery='';app.removeAttribute('aria-busy');render();}catch(e){if(version===loadVersion){app.removeAttribute('aria-busy');}if(version===loadVersion)app.innerHTML=`<div class="error" role="alert">The model could not be loaded. ${button('Retry','retry')}</div>`;}}
function action(name,value){if(name==='random-model'){const pool=state.models.filter(m=>m.id!==state.model?.id);if(pool.length){state.query='';choose(pool[Math.floor(Math.random()*pool.length)].id);}return;}if(name==='model'){choose(value);return;}if(name==='retry'){choose(state.models[0].id);return;}if(name==='mode')state.mode=value;if(name==='order')state.order=value;if(name==='tag-effect')state.tagEffect=value;if(name==='match')state.match=value;if(name==='tag')state.tags=state.tags.includes(value)?state.tags.filter(t=>t!==value):[...state.tags,value];if(name==='clear')state.tags=[];if(name==='start'){const cards=selected();if(!cards.length)return;state.run=makeRun(cards,state.order==='random');state.index=0;state.revealed=false;state.hintShown=false;state.complete=false;window.scrollTo(0,0);}if(name==='exit'){state.run=null;state.complete=false;}if(name==='hint')state.hintShown=true;if(name==='reveal')state.revealed=true;if(name==='previous'&&state.index>0){state.index--;state.revealed=false;state.hintShown=false;}if(name==='next'&&state.revealed){if(state.index===state.run.length-1)state.complete=true;else{state.index++;state.revealed=false;state.hintShown=false;}}render();if(state.run&&!state.complete)app.querySelector('.flashcard')?.focus({preventScroll:true});}
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.value);});
app.addEventListener('toggle',e=>{if(e.target.matches('.advanced-options'))state.advancedOpen=e.target.open;},true);
app.addEventListener('input',e=>{if(e.target.id==='model-search'){state.query=e.target.value;updateLibrary();}if(e.target.id==='tag-search'){state.tagQuery=e.target.value;app.querySelector('#tag-results').innerHTML=tagChips();}});
document.addEventListener('keydown',e=>{if(e.repeat||!state.run||state.complete||e.altKey||e.ctrlKey||e.metaKey||(e.target.closest('input,select,textarea,[contenteditable=true]')))return;if(e.code==='Space'){e.preventDefault();if(!state.revealed)action('reveal');}if(e.key==='ArrowRight'){e.preventDefault();action('next');}if(e.key==='ArrowLeft'){e.preventDefault();action('previous');}});
try{const response=await fetch('./data/models.json');if(!response.ok)throw Error('Library unavailable');state.models=await response.json();if(!state.models.length)throw Error('No models available');const requested=new URLSearchParams(location.search).get('model');await choose(state.models.some(m=>m.id===requested)?requested:state.models[0].id);}catch(e){app.innerHTML='<div class="error" role="alert"><h1>Unable to load the library</h1><p>Check that the data files are available, then reload this page.</p><button class="secondary" onclick="location.reload()">Reload</button></div>';}
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'get_revision_selection',description:'Read the selected anatomy model, filters and current run position.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({model:state.model?.name,tags:state.tags,mode:state.mode,order:state.order,count:selected().length,position:state.run?state.index+1:null,complete:state.complete})});}catch{ /* Optional browser API. */ }}
